import java.util.Scanner

fun checkUser(t: String): Boolean {
    var c = 0
    var next = false
    var sc = 0

    // Validate username part (before @)
    for (i in t.indices) {
        if (t[i] == '@') {
            if (i + 1 == t.length) return false
            next = c > 0 && c < 17
            sc = i + 1
            break
        }
        val ch = t[i]
        if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_')) {
            return false
        }
        c++
    }

    if (!next) return false

    // Validate domain/resource part (after @)
    var sNext = false
    c = 0
    var turn = false
    var slash = false

    for (i in sc until t.length) {
        if (i + 1 == t.length && t[i] == '.') return false
        if (t[i] == '/') {
            if (i - 1 > 0 && t[i - 1] == '.') return false
            slash = true
            if (!turn) sNext = true
            sc = i + 1
            break
        }

        if (t[i] == '.') {
            turn = true
            if (c > 0 && c < 17) {
                c = 0
                continue
            } else return false
        }

        val ch = t[i]
        if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_')) {
            return false
        }
        c++
    }

    if (!sNext && slash) {
        // Slash before any dot
        c = 0
        for (i in sc until t.length) {
            val ch = t[i]
            if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_')) {
                return false
            }
            c++
        }
        return c > 0 && c < 17
    } else {
        if (slash) {
            // Slash after at least one dot
            c = 0
            for (i in sc until t.length) {
                val ch = t[i]
                if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_')) {
                    return false
                }
                c++
            }
            return c > 0 && c < 17
        }
        // No slash, just domain
        return true
    }
}

fun main() {
    val scanner = Scanner(System.`in`)
    val id = scanner.next()
    println(if (checkUser(id)) "YES" else "NO")
}

